INSERT INTO `settings` (`setting_key`, `setting_value`, `setting_group`) VALUES ('home_pf_videos', '["https://images.unsplash.com/photo-1574717024653-61fd2cf4d44d?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1611162617474-5b21e879e113?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1536440136628-849c177e76a1?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1522869635100-9f4c5e86aa37?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1626814026160-2237a95fc5a0?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1578022761797-b8636ac1773c?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70", "https://images.unsplash.com/photo-1571171637578-41bc2dd41cd2?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=70"]', 'home');
INSERT INTO `settings` (`setting_key`, `setting_value`, `setting_group`) VALUES ('home_pf_shorts', '["https://images.unsplash.com/photo-1616469829941-c7200edec809?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=70", "https://images.unsplash.com/photo-1511512578047-dfb367046420?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=70", "https://images.unsplash.com/photo-1601944179066-29786cb9d32a?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=70", "https://images.unsplash.com/photo-1611162616475-46b635cb6868?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=70", "https://images.unsplash.com/photo-1583337130417-3346a1be7dee?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=70"]', 'home');
INSERT INTO `settings` (`setting_key`, `setting_value`, `setting_group`) VALUES ('home_reviews_note', 'Sample testimonials shown for layout preview — replace with verified client feedback before launch.', 'home') ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`), `setting_group` = VALUES(`setting_group`);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (5, 'Professional Video Editing', 'professional-video-editing', 'Editing', 'fa-solid fa-video', 45.0, 'Creative, high-quality video editing tailored to your content and brand.', 'Creative, high-quality video editing tailored to your content and brand.', 'This is the core service: we take raw footage and turn it into a finished video that feels intentional from the first frame.\nYou get a story pass, a pacing pass, a colour grade and a sound balance — then clean exports for wherever the video is going.', 'Final MP4 (1080p or 4K)\nProject file on request\nStills for thumbnails and socials', 'Story-first edit structure\nColour correction and sound balance\nTitles, captions and lower thirds\nPlatform-ready exports (1080p / 4K)', 'https://media.w3.org/2010/05/video/movie_300.mp4', 'https://images.pexels.com/videos/39681078/b-roll-freelancing-macbook-39681078.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200', 'video', 'media.w3.org', '[{"id": 4, "title": "Product Launch Promo", "description": "Thirty-second launch promo with motion graphics and grade.", "video_url": "https://media.w3.org/2010/05/bunny/trailer.mp4", "thumbnail_url": "https://images.pexels.com/videos/1536321/free-video-1536321.jpg?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200", "duration": "0:30", "embed_provider": "media.w3.org", "embed_type": "video", "embed_url": "https://media.w3.org/2010/05/bunny/trailer.mp4"}]', 1, 1);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (1, 'YouTube Editing', 'youtube-editing', 'Editing', 'fa-brands fa-youtube', 45.0, 'Retention-focused long-form edits that keep viewers watching till the end.', 'Retention-focused long-form edits that keep viewers watching till the end.', 'A YouTube edit is more than cutting clips together. We build the story first, then cut to a rhythm that survives the first 30 seconds.\nEvery project includes a pacing pass, caption styling, sound balance and a colour pass so the final export looks and sounds intentional on any device.', 'Final MP4 (1080p or 4K)\nProject file on request\nThumbnail-ready stills', 'Pacing pass and story structure\nCaptions, titles and lower thirds\nColour correction and sound balance\nPlatform-ready exports (1080p / 4K)', 'https://media.w3.org/2010/05/sintel/trailer.mp4', 'https://images.pexels.com/videos/36036747/pexels-photo-36036747.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200', 'video', 'media.w3.org', '[{"id": 1, "title": "Studio Session", "description": "Full edit breakdown of a studio interview — cut, grade and sound pass.", "video_url": "https://media.w3.org/2010/05/video/movie_300.mp4", "thumbnail_url": "https://images.pexels.com/videos/39681078/b-roll-freelancing-macbook-39681078.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200", "duration": "0:33", "embed_provider": "media.w3.org", "embed_type": "video", "embed_url": "https://media.w3.org/2010/05/video/movie_300.mp4"}, {"id": 3, "title": "Timeline Craft", "description": "Narrative documentary cut with a paced voice-over bed.", "video_url": "https://www.w3schools.com/html/mov_bbb.mp4", "thumbnail_url": "https://images.pexels.com/videos/36036747/pexels-photo-36036747.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200", "duration": "0:27", "embed_provider": "w3schools.com", "embed_type": "video", "embed_url": "https://www.w3schools.com/html/mov_bbb.mp4"}]', 1, 2);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (2, 'Shorts & Reels', 'shorts-reels', 'Editing', 'fa-solid fa-mobile-screen', 25.0, 'Punchy vertical cuts for TikTok, Reels and Shorts — built to go viral.', 'Punchy vertical cuts for TikTok, Reels and Shorts — built to go viral.', 'Short-form is a different craft: the hook decides everything. We cut for retention with fast hooks, tight pacing and captions that stay readable on a phone.\nEach delivery lands as a ready-to-upload vertical file with safe margins for every platform.', '9:16 MP4 exports\nCaption file (.srt) on request', 'Hook in the first 2 seconds\nBeat-matched cuts and zooms\nBold on-screen captions\n9:16 exports ready to upload', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://images.pexels.com/videos/8360178/blogger-challenge-content-creating-8360178.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=630', 'video', 'w3schools.com', '[{"id": 2, "title": "Creator Short", "description": "A 15-second vertical hook built for Shorts and Reels.", "video_url": "https://media.w3.org/2010/05/sintel/trailer.mp4", "thumbnail_url": "https://images.pexels.com/videos/8360178/blogger-challenge-content-creating-8360178.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=630", "duration": "0:15", "embed_provider": "media.w3.org", "embed_type": "video", "embed_url": "https://media.w3.org/2010/05/sintel/trailer.mp4"}]', 1, 3);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (3, 'Motion Graphics', 'motion-graphics', 'Design', 'fa-solid fa-wand-magic-sparkles', 60.0, 'Custom intros, lower thirds and animated graphics that elevate your brand.', 'Custom intros, lower thirds and animated graphics that elevate your brand.', 'Motion graphics should explain something in half a second. We design clean, on-brand animation that supports the edit instead of competing with it.\nDelivered as ready-to-drop clips in your brand colours, type and pacing.', 'Rendered animation clips\nAlpha-channel exports on request', 'Custom vector animation\nLogo reveals and transitions\nTracked callouts and stats\nBrand-consistent styling', 'https://media.w3.org/2010/05/bunny/trailer.mp4', 'https://images.pexels.com/photos/257904/pexels-photo-257904.jpeg?auto=compress&cs=tinysrgb&w=1200', 'video', 'media.w3.org', '[]', 1, 4);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (4, 'Thumbnail Design', 'thumbnail-design', 'Design', 'fa-solid fa-image', 15.0, 'Scroll-stopping, high-CTR thumbnails that boost your click-through rate.', 'Scroll-stopping, high-CTR thumbnails that boost your click-through rate.', 'A thumbnail is a tiny billboard. We design around one clear idea, keep contrast high and typography short so it still reads on a phone.\nYou get two variants per concept so you can test which one earns the click.', 'PNG + JPG at 1280×720\nEditable source file', 'Niche-based composition\nReadable text hierarchy\nFace cut-out and colour grading\nTwo variants per concept', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', 'https://images.pexels.com/photos/3379943/pexels-photo-3379943.jpeg?auto=compress&cs=tinysrgb&w=1200', 'video', 'interactive-examples.mdn.mozilla.net', '[]', 1, 5);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (6, 'Brand Videos', 'brand-videos', 'Advertising', 'fa-solid fa-layer-group', 120.0, 'Promotional and corporate videos that tell your brand story with impact.', 'Promotional and corporate videos that tell your brand story with impact.', 'A brand film is the version of your story that people actually finish watching. We keep it short, specific and visually consistent with your identity.\nThe delivery includes the master film plus cutdowns sized for the platforms you actually post on.', 'Master film (1080p / 4K)\nSocial cutdowns', 'Narrative structure and voice-over bed\nBrand colour and type treatment\nMotion graphics package\nMusic licensing guidance', 'https://www.w3schools.com/html/movie.mp4', 'https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&w=1200', 'video', 'w3schools.com', '[]', 1, 6);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (8, 'Social Media Ads', 'social-media-ads', 'Advertising', 'fa-solid fa-bullhorn', 75.0, 'High-converting ad creatives for Facebook, Instagram, TikTok and Reels.', 'High-converting ad creatives for Facebook, Instagram, TikTok and Reels.', 'Paid social lives or dies on the first two seconds. We build each creative around one clear promise, then cut square, vertical and landscape versions so the same idea runs on every placement.\nEvery ad set ships with hook variants, so you can test what actually converts instead of guessing.', 'Master ad + placement exports\nHook variant cuts', 'Hook variants for A/B testing\n9:16, 1:1 and 16:9 versions\nBurned-in captions\nSafe-zone checked for each platform', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', 'https://images.pexels.com/photos/8108091/pexels-photo-8108091.jpeg?auto=compress&cs=tinysrgb&w=1200', 'video', 'interactive-examples.mdn.mozilla.net', '[]', 1, 7);
INSERT INTO `services` (`id`, `name`, `slug`, `category`, `icon`, `price_from`, `subtitle`, `description`, `long_description`, `deliverables`, `bullet_points`, `file_path`, `thumbnail_path`, `embed_type`, `embed_provider`, `demo_videos_json`, `is_active`, `sort_order`) VALUES (9, 'Product Videos', 'product-videos', 'Advertising', 'fa-solid fa-box-open', 150.0, 'Clean, engaging product showcases that turn viewers into customers.', 'Clean, engaging product showcases that turn viewers into customers.', 'A product video has one job: make the object feel worth owning. We build around clean product moments, add motion callouts for the details that matter and keep the pace short enough to finish.\nDeliverables are sized for both your product page and paid placements.', 'Master product video (1080p / 4K)\nSquare and vertical cutdowns', 'Product hero and detail passes\nMotion callouts and labels\nClean background and grade\nCutdowns for ads and product pages', 'https://test-videos.co.uk/vids/bigbuckbunny/mp4/h264/720/Big_Buck_Bunny_720_10s_1MB.mp4', 'https://images.pexels.com/photos/66134/pexels-photo-66134.jpeg?auto=compress&cs=tinysrgb&w=1200', 'video', 'test-videos.co.uk', '[]', 1, 8);
