INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (1, 'Rowshan Taieen', 'rowshan-taieen', 'Founder & Lead Mentor', 'বাংলাদেশের ইনফরমেটিক কন্টেন্ট এর পুরো প্যাটার্ন পাল্টে দিয়েছি আমি Voice of Dhaka এর হাত ধরে। সাথে বাংলাদেশের টপ সব চ্যানেলে এডিটিং করে যাচ্ছি আর নিজের হাতে তৈরি করা বড় ভিডিও ইন্টারন্যাশনাল মার্কেটপ্লেসে নিজেদের আলাদা জায়গা করে নিয়েছে।', 'রোশন তাইয়িন মেক্সা মোশনের প্রতিষ্ঠাতা ও লিড মেন্টর। ছয় বছরের বেশি সময় ধরে বাংলাদেশের টপ চ্যানেলগুলোর এডিটিং টিম পরিচালনা করেছেন, ভয়েস অফ ঢাকার হাত ধরে ইনফরমেটিক কন্টেন্টের প্যাটার্ন বদলে দেওয়ার কাজে যুক্ত ছিলেন। এডিটিং, স্টোরিটেলিং ও টিম লিডিং — তিনটাতেই তাঁর মূল দক্ষতা। স্টুডিওতে তিনিই প্রতিটি প্রজেক্টের ফাইনাল কোয়ালিটি রিভিউ করেন এবং নতুন মেম্বারদের মেন্টরিং করেন।', 'Storytelling\nPremiere Pro\nTeam leadership\nClient communication\nCreative direction\nPost-production strategy', 'সব প্রজেক্টের ফাইনাল কোয়ালিটি রিভিউ\nনতুন ক্লায়েন্টের ব্রিফ ও টাইমলাইন কনফার্ম\nটিম মেম্বারদের মেন্টরিং ও ট্রেনিং\nব্র্যান্ড স্ট্যান্ডার্ড ঠিক রাখা', 'assets/images/team/member-1-rowshan-taieen.jpg', '', '', '', '', 1, 1, 0);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (2, 'Arif Hossain', 'arif-hossain', 'Senior Video Editor', 'Long-form edits with a story-first structure and a pacing pass on every cut.', 'Dhaka-based editor with seven years behind the timeline, most of them spent cutting long-form for YouTube creators and course sellers. Arif takes raw footage and builds a story with a clear opening, a pace that holds attention past the ten-minute mark and an ending that lands, then hands the cut to colour and sound with clean, labelled project files. His strengths are story structure, pacing and dialogue-driven editing in Premiere Pro. Inside the studio he leads the first cut on every long-form project and mentors the junior editors on retention-focused pacing.', 'Story structure\nPacing & rhythm\nPremiere Pro\nAudio cleanup\nCaption styling', 'Leads the first cut and story pass on long-form projects\nReviews editor drafts before they reach the client\nKeeps project files and export naming consistent\nTrains junior editors on retention-focused pacing', 'assets/images/team/member-2-arif-hossain.jpg', '', '', '', '', 0, 1, 1);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (3, 'Nusrat Jahan', 'nusrat-jahan', 'YouTube Editor', 'Runs the weekly upload cycle — chapters, captions and on-time delivery.', 'Nusrat is the editor most clients talk to every week. She runs the upload cycle for creator channels — turning long interviews into watchable chapters, styling captions, cutting dead air and making sure each video is finished before the scheduled publish time without sanding off the creator\'s own tone. She works fast in Premiere Pro and is unusually good at reading a rough transcript to find the best twenty seconds. In the team she owns weekly delivery and coordinates the publish calendar with clients.', 'Interview editing\nCaption styling\nChapter markers\nThumbnail stills\nWorkflow planning', 'Cuts and delivers weekly channel uploads\nPrepares chapter markers and caption files\nCoordinates the publish schedule with clients\nFlags footage gaps before the edit starts', 'assets/images/team/member-3-nusrat-jahan.jpg', '', '', '', '', 0, 1, 2);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (4, 'Tanvir Ahmed', 'tanvir-ahmed', 'Motion Graphics Designer', 'Builds the animated layer of the brand — reveals, lower thirds, callouts.', 'Tanvir brings five years of After Effects work across brand films, ads and creator channels. He designs the animated layer of a video: logo reveals, lower thirds, stat callouts, transitions and the small motion details that make an edit feel expensive, all built around the client\'s type and colour system. His strengths are vector animation, kinetic type and clean transitions that never distract from the story. He owns the studio\'s motion template library, so every editor can drop in an intro that already looks on brand.', 'After Effects\nLogo animation\nLower thirds\nVector illustration\nBrand systems', 'Designs intros, transitions and callout animations\nKeeps motion assets on brand and reusable\nExports alpha-channel versions for editors\nMaintains the shared motion template library', 'assets/images/team/member-4-tanvir-ahmed.jpg', '', '', '', '', 0, 1, 3);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (5, 'Sadia Islam', 'sadia-islam', 'Thumbnail Designer', 'One clear idea per thumbnail, two variants for testing.', 'Sadia designs the frame that decides whether a video gets watched at all. From a graphic design background with four years of YouTube thumbnails, she works one clear idea per image: high contrast, short readable type and a face expression that matches the promise of the title — always in two variants so clients can test the click. Her toolkit is Photoshop, composition and type hierarchy. She keeps every channel\'s thumbnails visually consistent and delivers platform-ready 1280×720 exports.', 'Photoshop\nComposition\nTypography\nFace cut-outs\nA/B variants', 'Designs two thumbnail variants per concept\nKeeps a consistent look across a channel\nMatches the thumbnail promise to the video content\nDelivers 1280×720 PNG and JPG exports', 'assets/images/team/member-5-sadia-islam.jpg', '', '', '', '', 0, 1, 4);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (6, 'Rakib Hasan', 'rakib-hasan', 'Colourist & Sound Designer', 'The finishing pass — honest skin tones, clean dialogue, balanced music.', 'Rakib is the last person to touch a project before it ships. With six years of grading and mixing, he fixes skin tones, balances exposure between shots, cleans dialogue down to the room tone and sits the music under the voice so nothing fights. He grades in DaVinci Resolve, mixes to platform loudness standards and prepares the final export settings. In the studio he owns the finishing pass, so every delivery leaves with a consistent look and a mix that survives phone speakers.', 'DaVinci Resolve\nColour grading\nNoise removal\nAudio mixing\nLoudness standards', 'Grades every delivery for consistency\nCleans dialogue and balances music beds\nChecks loudness across platforms\nPrepares platform-ready export settings', 'assets/images/team/member-6-rakib-hasan.jpg', '', '', '', '', 0, 1, 5);
INSERT INTO `team_members` (`id`, `name`, `slug`, `role`, `bio`, `description`, `skills`, `responsibilities`, `file_path`, `whatsapp`, `telegram`, `phone`, `email`, `is_founder`, `is_active`, `sort_order`) VALUES (7, 'Mim Akter', 'mim-akter', 'Shorts & Reels Editor', 'Vertical hooks in the first two seconds, captions that stay readable.', 'Mim cuts the vertical side of the studio. She started as a creator editing her own Reels and now cuts Shorts, Reels and TikToks for brands and creators full time — hooks in the first two seconds, beat-matched cuts, captions that stay readable on a small screen and safe margins so nothing hides under the app UI. She is fast with vertical framing, hook variants and caption styling. She owns short-form delivery in the team and tests hooks before anything goes out.', 'Vertical editing\nHook writing\nBeat sync\nOn-screen captions\n9:16 exports', 'Cuts verticals from long-form and raw footage\nTests hooks before final delivery\nDelivers 9:16, 1:1 and 16:9 versions\nKeeps caption style consistent per client', 'assets/images/team/member-7-mim-akter.jpg', '', '', '', '', 0, 1, 6);
